package cc.onemem.usage;
import android.app.*;
import android.appwidget.AppWidgetManager;
import android.content.*;
import android.graphics.Color;
import android.os.*;
import android.view.*;
import android.webkit.*;
import org.json.*;
import java.io.*;
import java.util.concurrent.*;

public class MainActivity extends Activity {
  private WebView web;private Store store;private final ExecutorService pool=Executors.newFixedThreadPool(4);
  @Override public void onCreate(Bundle state){super.onCreate(state);store=new Store(this);web=new WebView(this);web.setBackgroundColor(Color.WHITE);getWindow().setStatusBarColor(Color.WHITE);getWindow().setNavigationBarColor(Color.WHITE);getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR);android.widget.FrameLayout root=new android.widget.FrameLayout(this);root.addView(web,new android.widget.FrameLayout.LayoutParams(-1,-1));setContentView(root);
    root.setOnApplyWindowInsetsListener((v,insets)->{if(Build.VERSION.SDK_INT>=30){android.graphics.Insets i=insets.getInsets(WindowInsets.Type.systemBars()|WindowInsets.Type.displayCutout()|WindowInsets.Type.ime());v.setPadding(i.left,i.top,i.right,i.bottom);}else v.setPadding(insets.getSystemWindowInsetLeft(),insets.getSystemWindowInsetTop(),insets.getSystemWindowInsetRight(),insets.getSystemWindowInsetBottom());return insets;});root.requestApplyInsets();
    WebSettings s=web.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setAllowFileAccess(false);s.setAllowContentAccess(false);s.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);s.setSupportMultipleWindows(false);web.addJavascriptInterface(new Bridge(),"Android");web.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView view,WebResourceRequest req){return !"app.local".equals(req.getUrl().getHost());}@Override public WebResourceResponse shouldInterceptRequest(WebView view,WebResourceRequest req){String host=req.getUrl().getHost();if(!"app.local".equals(host))return new WebResourceResponse("text/plain","UTF-8",new ByteArrayInputStream(new byte[0]));String path=req.getUrl().getPath();if(path==null||path.contains(".."))return null;try{String name=path.substring(1);String mime=name.endsWith(".js")?"application/javascript":name.endsWith(".css")?"text/css":name.endsWith(".html")?"text/html":name.endsWith(".woff2")?"font/woff2":name.endsWith(".svg")?"image/svg+xml":"application/octet-stream";return new WebResourceResponse(mime,"UTF-8",getAssets().open(name));}catch(IOException e){return new WebResourceResponse("text/plain","UTF-8",new ByteArrayInputStream(new byte[0]));}}});
    web.loadUrl("https://app.local/native.html");if(Build.VERSION.SDK_INT>=33)getOnBackInvokedDispatcher().registerOnBackInvokedCallback(0,()->onBackPressed());UpdateService.schedule(this);pool.execute(()->WidgetPin.publishPreviews(this));}
  @Override public void onBackPressed(){web.evaluateJavascript("window.__nativeBack&&window.__nativeBack()",null);}
  @Override public void onConfigurationChanged(android.content.res.Configuration config){super.onConfigurationChanged(config);web.evaluateJavascript("window.dispatchEvent(new Event('nativeappearancechange'))",null);}
  @Override protected void onDestroy(){pool.shutdownNow();web.removeJavascriptInterface("Android");web.destroy();super.onDestroy();}
  final class Bridge { @JavascriptInterface public void call(String id,String operation,String payload){pool.execute(()->{try{JSONObject p=new JSONObject(payload);Object result;
    switch(operation){case "config":result=store.publicConfig();break;case "saveConfig":store.save(p.getJSONObject("config"));UpdateService.schedule(MainActivity.this);QuotaWidget.updateAll(MainActivity.this);result=true;break;
    case "testConfig":JSONObject test=p.getJSONObject("config");JSONArray cs=test.getJSONArray("connections");JSONObject candidate=null;for(int i=0;i<cs.length();i++)if(cs.getJSONObject(i).optString("id").equals(test.optString("selected")))candidate=cs.getJSONObject(i);if(candidate==null)throw new Exception("请选择服务连接");if(candidate.optString("key").isEmpty()){JSONArray saved=store.config().getJSONArray("connections");for(int i=0;i<saved.length();i++)if(saved.getJSONObject(i).optString("id").equals(candidate.optString("id")))candidate.put("key",saved.getJSONObject(i).optString("key"));}new Api(store,candidate).get("/admin/groups/all?platform=openai");result=true;break;
    case "savePreferences":synchronized(store){JSONObject cfg=store.config(),pref=p.getJSONObject("preferences");if(pref.has("interval")){int interval=pref.getInt("interval");if(interval!=1&&interval!=5&&interval!=10&&interval!=15&&interval!=30&&interval!=60)throw new Exception("无效刷新间隔");cfg.put("interval",interval);}if(pref.has("theme")){String theme=pref.getString("theme");if(!theme.equals("light")&&!theme.equals("dark")&&!theme.equals("system"))throw new Exception("无效外观");cfg.put("theme",theme);}if(pref.has("refreshOnOpen"))cfg.put("refreshOnOpen",pref.getBoolean("refreshOnOpen"));store.save(cfg);}UpdateService.schedule(MainActivity.this);QuotaWidget.updateAll(MainActivity.this);result=true;break;
    case "systemAppearance":result=new JSONObject().put("dark",(getResources().getConfiguration().uiMode&android.content.res.Configuration.UI_MODE_NIGHT_MASK)==android.content.res.Configuration.UI_MODE_NIGHT_YES);break;
    case "appearance":boolean dark=p.optBoolean("dark");runOnUiThread(()->{getWindow().getDecorView().setSystemUiVisibility(dark?0:View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR);int color=dark?0xff242529:Color.WHITE;web.setBackgroundColor(color);if(Build.VERSION.SDK_INT>=29)web.getSettings().setForceDark(WebSettings.FORCE_DARK_OFF);getWindow().getDecorView().setBackgroundColor(color);((ViewGroup)findViewById(android.R.id.content)).getChildAt(0).setBackgroundColor(color);getWindow().setStatusBarColor(color);getWindow().setNavigationBarColor(color);});result=true;break;
    case "accountSettings":case "accountProxies":case "saveAccountSettings":result=AccountAdmin.execute(new Api(store),operation,p);break;
    case "api":result=new Api(store).get(p.getString("path"));break;case "resetOpenAIQuota":result=new Api(store).resetOpenAIQuota(p.getInt("accountId"),p.optBoolean("confirmed",false));break;case "getCache":result=store.cache(p.getString("key"));break;case "setCache":store.cache(p.getString("key"),p.get("value"));QuotaWidget.updateAll(MainActivity.this);result=true;break;
    case "pinWidget":result=WidgetPin.request(MainActivity.this,"wide".equals(p.optString("size")));break;
    case "widgetStatus":result=WidgetPin.status(MainActivity.this);break;
    case "hideKeyboard":runOnUiThread(()->{web.clearFocus();((android.view.inputmethod.InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(web.getWindowToken(),0);});result=true;break;
    case "background":runOnUiThread(()->moveTaskToBack(true));result=true;break;default:throw new Exception("不支持的操作");}
    reply(id,result,null);
  }catch(Exception e){String message=e instanceof java.net.SocketTimeoutException?"网络超时，请重试":e instanceof java.net.UnknownHostException?"网络不可用，请检查连接":e instanceof javax.net.ssl.SSLException?"安全连接失败，请检查服务地址":e instanceof IOException?"网络连接失败，请稍后重试":e.getMessage();reply(id,null,message==null?"操作失败":message);}});}}
  private void reply(String id,Object result,String error){String encoded=new JSONArray().put(result==null?JSONObject.NULL:result).toString();encoded=encoded.substring(1,encoded.length()-1);String js="window.__nativeReply&&window.__nativeReply("+JSONObject.quote(id)+","+encoded+","+(error==null?"null":JSONObject.quote(error))+")";runOnUiThread(()->{if(!isFinishing())web.evaluateJavascript(js,null);});}
}
